/* SPDX-License-Identifier: GPL-3.0-or-later */
#include "llm/mojo.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
char *janas_getenv(const char *name) { (void)name; return NULL; }
int janas_kernels_ref(void) { return 0; }
int main(void) {
    struct janas_mojo_stats s;
    assert(!janas_mojo_available());
    janas_mojo_set_enabled(1);
    assert(!janas_mojo_enabled());
    assert(strstr(janas_mojo_status(), "ARM64"));
    assert(janas_mojo_panel_rows(12, NULL, 0, NULL, NULL, 0, NULL, 2, NULL, 0) == 0);
    janas_mojo_get_stats(&s);
    assert(!s.calls && !s.rows && !s.row_vectors && !s.refusals);
    janas_mojo_set_enabled(0);
    assert(!janas_mojo_enabled());
    puts("portable x64 Mojo refusal and C fallback: ok");
    return 0;
}
